const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Scale SEAL Leaderboards: Frontier Model Performance";
pres.author = "Scale Labs";

// Color palette - Midnight Executive + lab-specific colors
const COLORS = {
  darkBg: "1E2761",
  lightBg: "F8F9FC",
  openai: "10A14A",
  google: "4285F4",
  anthropic: "D4A017",
  muse: "E64980",
  accent: "6C63FF",
  text: "1E293B",
  muted: "64748B",
  white: "FFFFFF",
  lightGray: "E2E8F0",
  cardBg: "FFFFFF"
};

// Helper for shadows (fresh object each time)
const cardShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.1 });

// ============ SLIDE 1: Title Slide ============
const slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Decorative top bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08, fill: { color: COLORS.accent }
});

// Scale badge
slide1.addText("SCALE LABS", {
  x: 0.6, y: 0.4, w: 1.8, h: 0.35,
  fontSize: 10, bold: true, color: COLORS.white, charSpacing: 4
});

// Main title
slide1.addText("Scale SEAL Leaderboards", {
  x: 0.6, y: 1.5, w: 8.8, h: 0.9,
  fontSize: 44, bold: true, color: COLORS.white, fontFace: "Arial"
});

// Subtitle
slide1.addText("Frontier Model Performance Across 20+ AI Benchmarks", {
  x: 0.6, y: 2.5, w: 8.8, h: 0.5,
  fontSize: 22, color: COLORS.white, fontFace: "Arial"
});

// Divider line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.6, y: 3.2, w: 2, h: 0.04, fill: { color: COLORS.accent }
});

// Stats row
