  { bench: "MCP Atlas (Tool Use)", winner: "Muse", wins: ["Muse Spark"] },
  { bench: "SWE-Bench Pro (Public)", winner: "OpenAI", wins: ["GPT-5.4-pro"] },
  { bench: "SWE-Bench Pro (Private)", winner: "Anthropic", wins: ["Claude Opus 4.6"] },
  { bench: "Humanity's Last Exam", winner: "OpenAI", wins: ["GPT-5.4-pro"] },
  { bench: "MultiChallenge", winner: "Muse", wins: ["Muse Spark"] },
  { bench: "EnigmaEval", winner: "OpenAI", wins: ["GPT-5.4-pro"] },
  { bench: "AudioMulti (Text)", winner: "Google", wins: ["Gemini-3-pro"] },
  { bench: "AudioMulti (Audio)", winner: "Google", wins: ["Gemini-3.1-flash"] },
  { bench: "VISTA Vision", winner: "Google", wins: ["Gemini 2.5 Pro"] },
  { bench: "MASK Honesty", winner: "Anthropic", wins: ["Claude Opus 4.6"] },
  { bench: "Professional – Legal", winner: "Anthropic", wins: ["Claude Opus 4.6"] },
  { bench: "Professional – Finance", winner: "Anthropic", wins: ["Claude Opus 4.6"] }
];

const labColors = {
  "OpenAI": COLORS.openai,
  "Google": COLORS.google,
  "Anthropic": COLORS.anthropic,
  "Muse": COLORS.muse
};

matrixData.forEach((row, ri) => {
  const y = heatmapY + rowH * 0.6 + ri * rowH;
  const bgColor = ri % 2 === 0 ? COLORS.white : "F8FAFC";

  // Benchmark name
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y, w: benchmarkColW, h: rowH, fill: { color: bgColor }
  });
  slide7.addText(row.bench, {
    x: 0.6, y, w: benchmarkColW - 0.2, h: rowH, fontSize: 9, color: COLORS.text, valign: "middle"
  });

  // Lab cells
  labs.forEach((lab, li) => {
    const x = 0.5 + benchmarkColW + li * labColW;
    const isWinner = row.winner === lab;
    const cellColor = isWinner ? labColors[lab] : bgColor;

    slide7.addShape(pres.shapes.RECTANGLE, {
      x, y, w: labColW, h: rowH, fill: { color: cellColor }
    });

    if (isWinner) {
      slide7.addText("●", {
        x, y, w: labColW, h: rowH, fontSize: 14, color: COLORS.white, align: "center", valign: "middle"
      });
    }
  });
});

// Legend
slide7.addText("OpenAI leads coding & reasoning  |  Google leads multimodal  |  Anthropic leads safety  |  Muse emerging", {
  x: 0.5, y: 5.2, w: 9, h: 0.3, fontSize: 10, color: COLORS.muted
});

// ============ SLIDE 8: Key Takeaways ============
const slide8 = pres.addSlide();
slide8.background = { color: COLORS.darkBg };

// Top accent bar
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08, fill: { color: COLORS.accent }
});

// Title
slide8.addText("Key Takeaways", {
  x: 0.6, y: 0.4, w: 9, h: 0.6, fontSize: 32, bold: true, color: COLORS.white
});

slide8.addText("Specialization is the defining trend in frontier AI", {
  x: 0.6, y: 0.95, w: 9, h: 0.35, fontSize: 16, color: "94A3B8"
});

// Takeaway cards - 2x2 grid
const takeaways = [
  {
    icon: "1",
    title: "GPT-5.4 Leads Agentic & Reasoning",
    detail: "Dominates SWE Atlas, SWE-Bench Pro, Humanity's Last Exam, and EnigmaEval. OpenAI's coding and reasoning lead is clear.",
    color: COLORS.openai
  },
  {
    icon: "2",
    title: "Gemini Dominates Audio/Vision",
    detail: "Sweeps all AudioMultiChallenge benchmarks (Text and Audio output) and VISTA vision-language. Google owns multimodal.",
    color: COLORS.google
  },
  {
    icon: "3",
    title: "Claude Leads Safety & Honesty",
    detail: "96%+ on MASK honesty, #1 on Professional Reasoning (Legal & Finance). But Fortress scores (8–13) reveal critical vulnerability.",
    color: COLORS.anthropic
  },
  {
    icon: "4",
    title: "Muse Spark: Strong New Entrant",
    detail: "Ranks top 3 on 6+ benchmarks including #1 on MultiChallenge (75.5%) and MCP Atlas Tool Use (78.3%). One to watch.",
    color: COLORS.muse
  }
];

const cardW2 = 4.3;
const cardH2 = 1.6;
const cardStartY = 1.5;
const cardGapX = 0.3;
const cardGapY = 0.25;

takeaways.forEach((t, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const x = 0.6 + col * (cardW2 + cardGapX);
  const y = cardStartY + row * (cardH2 + cardGapY);

  // Card background
  slide8.addShape(pres.shapes.RECTANGLE, {
    x, y, w: cardW2, h: cardH2, fill: { color: "2D3A6E" }
  });

  // Accent strip
  slide8.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h: cardH2, fill: { color: t.color }
  });

  // Number circle
  slide8.addShape(pres.shapes.OVAL, {
    x: x + 0.2, y: y + 0.15, w: 0.35, h: 0.35, fill: { color: t.color }
  });
  slide8.addText(t.icon, {
    x: x + 0.2, y: y + 0.15, w: 0.35, h: 0.35, fontSize: 12, bold: true, color: COLORS.white, align: "center", valign: "middle"
  });

  // Title
  slide8.addText(t.title, {
    x: x + 0.65, y: y + 0.15, w: cardW2 - 0.85, h: 0.35, fontSize: 13, bold: true, color: COLORS.white
  });

  // Detail
  slide8.addText(t.detail, {
    x: x + 0.2, y: y + 0.6, w: cardW2 - 0.4, h: 0.9, fontSize: 10, color: "94A3B8", valign: "top"
  });
});

// Unsaturation insight
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0.6, y: 4.85, w: 8.8, h: 0.55, fill: { color: COLORS.accent, transparency: 20 }
});
slide8.addText("Benchmarks remain unsaturated: HLE (44%), EnigmaEval (24%), SciPredict (25%) — substantial room for improvement across all frontier models", {
  x: 0.8, y: 4.85, w: 8.4, h: 0.55, fontSize: 11, color: COLORS.white, valign: "middle"
});

// Save
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved to /app/output/final_deck.pptx"))
  .catch(err => console.error("Error:", err));

