slide7.addText("Competitive landscape mapping #1-ranked lab across each benchmark domain", {
  x: 0.5, y: 0.85, w: 9, h: 0.3, fontSize: 12, color: COLORS.muted
});

// Heatmap matrix - benchmark vs domain
const heatmapY = 1.3;
const heatmapRowH = 0.65;
const benchmarkColW = 2.5;
const labColW = 1.5;

// Column headers
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: heatmapY, w: benchmarkColW, h: rowH * 0.6, fill: { color: COLORS.darkBg }
});
slide7.addText("Benchmark", { x: 0.5, y: heatmapY, w: benchmarkColW, h: rowH * 0.6, fontSize: 10, bold: true, color: COLORS.white, align: "center", valign: "middle" });

const labs = ["OpenAI", "Google", "Anthropic", "Muse"];
labs.forEach((lab, li) => {
  const x = 0.5 + benchmarkColW + li * labColW;
  slide7.addShape(pres.shapes.RECTANGLE, {
    x, y: heatmapY, w: labColW, h: rowH * 0.6, fill: { color: COLORS.darkBg }
  });
  slide7.addText(lab, { x, y: heatmapY, w: labColW, h: rowH * 0.6, fontSize: 10, bold: true, color: COLORS.white, align: "center", valign: "middle" });
});

// Data rows
const matrixData = [
  { bench: "SWE Atlas – Test Writing", winner: "OpenAI", wins: ["GPT-5.4-xHigh"] },
  { bench: "SWE Atlas – Codebase QnA", winner: "OpenAI", wins: ["GPT-5.4-xHigh"] },

